const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const moroto = ee.Geometry.Point([34.666, 2.535]);
  const roi = moroto.buffer(40000); // 40 km radius

  // August 2023
  const start2023 = '2023-08-01';
  const end2023 = '2023-08-31';

  // August baseline 1991-2010 (use 2000-2010 for MODIS availability)
  const startBaseline = '2000-08-01';
  const endBaseline = '2010-08-31';

  // 2. Data Acquisition - August 2023 (MODIS)
  let col2023 = ee.ImageCollection('MODIS/061/MOD13A2')
    .filterBounds(roi)
    .filter(ee.Filter.calendarRange(2023, 2023, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .select('NDVI');

  const size2023 = await col2023.size().getInfo();
  console.log(`2023 Images: ${size2023}`);

  if (size2023 === 0) {
    console.log("No MODIS data for August 2023.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Process 2023 data
  const ndvi2023 = col2023.mean().multiply(0.0001); // Scale factor

  const stats2023 = await ndvi2023.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const mean2023 = stats2023.NDVI_mean;
  const count2023 = stats2023.NDVI_count;

  console.log(`2023: Mean NDVI = ${mean2023?.toFixed(4)}, Pixels = ${count2023}`);

  if (!count2023 || count2023 === 0) {
    console.log("No valid pixels for 2023.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 3. Historical baseline (2000-2010, August only)
  let colBaseline = ee.ImageCollection('MODIS/061/MOD13A2')
    .filterBounds(roi)
    .filter(ee.Filter.calendarRange(2000, 2010, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .select('NDVI');

  const sizeBaseline = await colBaseline.size().getInfo();
  console.log(`Baseline Images (2000-2010): ${sizeBaseline}`);

  if (sizeBaseline === 0) {
    console.log("No baseline data.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Process baseline data
  const ndviBaseline = colBaseline.mean().multiply(0.0001);

  const statsBaseline = await ndviBaseline.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const meanBaseline = statsBaseline.NDVI_mean;
  const countBaseline = statsBaseline.NDVI_count;

  console.log(`Baseline: Mean NDVI = ${meanBaseline?.toFixed(4)}, Pixels = ${countBaseline}`);

  if (!countBaseline || countBaseline === 0) {
    console.log("No valid pixels for baseline.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (mean2023 == null || meanBaseline == null || 
      isNaN(mean2023) || isNaN(meanBaseline) ||
      mean2023 < -1 || mean2023 > 1 || 
      meanBaseline < -1 || meanBaseline > 1) {
    console.log("Invalid NDVI values.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`\nComparison: 2023 (${mean2023.toFixed(4)}) vs Baseline (${meanBaseline.toFixed(4)})`);
  console.log(`Difference: ${(mean2023 - meanBaseline).toFixed(4)}`);

  if (mean2023 < meanBaseline) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
